file.content:
            event_is_attested = event.get("mode") == SYNC_MODE_ATTESTED
            if mode == SYNC_MODE_PLAIN and event_is_attested:
                continue
            if mode == SYNC_MODE_ATTESTED and not event_is_attested:
                continue
            # Prefer the summary frozen into the event when it was
            # recorded. Events written before summaries were frozen fall
            # back to resolving the tip live; a tip that no longer
            # resolves anywhere is omitted rather than misordered.
            height = event.get("height")
            length = event.get("length")
            status = event.get("status")
            if (
                not isinstance(height, int)
                or isinstance(height, bool)
                or length is None
                or status is None
            ):
                descriptor = self._tip_descriptor(event.get("tip_hash"))
                if descriptor is None:
                    continue
                height = descriptor["height"]
                length = descriptor["length"]
                status = descriptor["status"]
            if min_height is not None and height < min_height:
                continue
            if max_height is not None and height > max_height:
                continue
            # New events always carry the deadline; a legacy adopted
            # event predating the field inherits it from its still-live
            # sync record when possible.
            expires_at = event.get("expires_at")
            if expires_at is None:
                is_attested = event.get("mode") == SYNC_MODE_ATTESTED
                table = (
                    self.store.attested_syncs
                    if is_attested
                    else self.store.syncs
                )
                live_rec = table.get(
                    (event.get("source"), event.get("request_id"))
                )
                if (
                    live_rec is not None
                    and live_rec.get("tip_hash") == event.get("tip_hash")
                ):
                    expires_at = live_rec.get("expires_at")
            rows.append(
                {
                    "event_id": event["event_id"],
                    "kind": event_kind,
                    "at": event["at"],
                    "source": event.get("source"),
                    "request_id": event.get("request_id"),
                    "tip_hash": event.get("tip_hash"),
                    "height": height,
                    "length": length,
                    "status": status,
                    "expires_at": expires_at,
                }
            )

    rows.sort(
        key=lambda row: (
            row["height"],
            row["tip_hash"],
            row["source"],
            row["request_id"],
            row["event_id"],
        )
    )
    total = len(rows)
    if cursor > total:
        return 400, {"error": "cursor is beyond the result set"}
    items = rows[cursor : cursor + limit]
    next_cursor = cursor + limit if cursor + limit < total else None
    return 200, {"items": items, "total": total, "next_cursor": next_cursor}

# -- transaction index ----------------------------------------------------

INDEX_DEFAULT_LIMIT = 50
INDEX_MAX_LIMIT = 200

def list_transactions(self, params: dict) -> tuple[int, dict]:
    """GET /v1/index/transactions — paginated confirmed-chain tx index.

    Pending-tip transactions are excluded. Filters (AND-combined):
    ``tx_id`` (64 lowercase hex), ``account`` (matches sender or
    recipient), ``height``, the inclusive ``min_height``/``max_height``
    range (an exact ``height`` intersects with the range) and
    ``direction`` (``all`` keeps the sender-or-recipient account match,
    ``out`` matches senders only, ``in`` recipients only; ``in``/``out``
    require a non-empty ``account``); ``limit`` (default 50, range
    1-200) and ``cursor`` (default 0) paginate. Numeric filters must be
    plain decimals without leading zeros; any malformed value returns
    400. The range/direction parameters accept ASCII digits only and
    every violation of their rules — empty values, malformed heights,
    inverted bounds, an unknown direction, a missing account for
    ``in``/``out`` — returns the fixed ``400 {"error": "input"}``.
    Rows are ordered by (height, index, tx_id); ``index`` is the
    transaction's 0-based position inside its block, matching the Merkle
    proof index. A cursor beyond the filtered total returns 400, a cursor
    equal to it returns an empty page.

    The optional anchor pair ``at_height``/``at_hash`` fixes the query
    prefix to the confirmed main-chain blocks from genesis through the
    anchor block inclusive. The parameters are all-or-nothing: exactly
    one of them, an empty value, a malformed value (an ASCII
    non-negative decimal without leading zeros; a 64-char lowercase hex
    string) or a repeated occurrence returns the fixed
    ``400 {"error": "input"}``. With both present, an unknown anchor
    height (or one naming the pending tip) returns 404
    ``anchor_not_found`` and a confirmed block with a different hash
    returns 409 ``anchor_conflict``; candidate forks never satisfy an
    anchor. Anchor errors take precedence over the cursor-out-of-range
    check. With a valid prefix, the other filters still intersect it and
    ``total``/``next_cursor`` count only the fixed prefix, so pages
    taken under the same anchor stay identical as the chain tail grows
    or is rolled back.

    The optional ``include_summary`` accepts a single occurrence of
    ``true``/``false``; omitted or ``false`` the response is unchanged.
    An empty value, any other token (or a repeat, rejected at the HTTP
    layer) returns the fixed ``400 {"error": "input"}``. When ``true``
    a non-empty ``account`` is required (else the same fixed input
    error, answered before the anchor lookup) and the response adds
    ``summary`` with ``incoming_count``/``outgoing_count`` (the number
    of filtered transactions received/sent by the account),
    ``incoming_amount``/``outgoing_amount`` (the matching integer
    sums) and ``net_amount`` (incoming minus outgoing, may be
    negative). The summary spans the whole filtered confirmed set, not
    just the current page; a self-transfer occupies one row but adds
    one to both counts/amounts and zero to the net. An empty page at
    ``cursor == total`` still carries the full summary. All figures
    are integers.
    """
    tx_id = params.get("tx_id")
    if tx_id is not None and not crypto.is_hex64(tx_id):
        return 400, {"error": "tx_id must be 64 lowercase hex characters"}

    # include_summary is a strict single-occurrence true/false flag (the
    # repeat check lives in the HTTP layer). Every violation — empty
    # value, unknown token — maps to the contract-fixed
    # {"error": "input"} and is answered before the anchor is looked up.
    include_summary_raw = params.get("include_summary")
    if include_summary_raw is not None and include_summary_raw not in (
        "true",
        "false",
    ):
        return 400, {"error": "input"}
    include_summary = include_summary_raw == "true"

    # Anchor pair: all-or-nothing with strict formats. Every violation
    # maps to the contract-fixed {"error": "input"} and is answered
    # before any state is read.
    at_height_raw = params.get("at_height")
    at_hash = params.get("at_hash")
    anchor_present = at_height_raw is not None or at_hash is not None
    if anchor_present:
        if at_height_raw is None or at_hash is None:
            return 400, {"error": "input"}
        at_height = _parse_ascii_decimal(at_height_raw)
        if at_height is None or not crypto.is_hex64(at_hash):
            return 400, {"error": "input"}
    else:
        at_height = None

    # The range/direction parameters validate first so that every one of
    # their violations maps to the contract-fixed {"error": "input"} —
    # including ``in``/``out`` with an empty account, which would
    # otherwise fall into the legacy account message below.
    min_height = None
    if params.get("min_height") is not None:
        min_height = _parse_ascii_decimal(params["min_height"])
        if min_height is None:
            return 400, {"error": "input"}
    max_height = None
    if params.get("max_height") is not None:
        max_height = _parse_ascii_decimal(params["max_height"])
        if max_height is None:
            return 400, {"error": "input"}
    if (
        min_height is not None
        and max_height is not None
        and min_height > max_height
    ):
        return 400, {"error": "input"}
    direction = params.get("direction")
    if direction is None:
        direction = "all"
    elif direction not in ("all", "in", "out"):
        return 400, {"error": "input"}
    if direction in ("in", "out"):
        required_account = params.get("account")
        if not isinstance(required_account, str) or not required_account:
            return 400, {"error": "input"}

    account = params.get("account")
    # The summary is computed per account, so enabling it without a valid
    # account is the fixed input error; check it before the legacy account
    # message (which uses a different error body).
    if include_summary and not (
        isinstance(account, str) and account
    ):
        return 400, {"error": "input"}
    if account is not None and (not isinstance(account, str) or not account):
        return 400, {"error": "account must be a non-empty string"}

    height = None
    if params.get("height") is not None:
        height = _parse_decimal(params["height"])
        if height is None:
            return 400, {"error": "height must be a non-negative decimal"}
    limit = self.INDEX_DEFAULT_LIMIT
    if params.get("limit") is not None:
        parsed = _parse_decimal(params["limit"])
        if parsed is None or not 1 <= parsed <= self.INDEX_MAX_LIMIT:
            return 400, {"error": "limit must be a decimal between 1 and 200"}
        limit = parsed
    cursor = 0
    if params.get("cursor") is not None:
        parsed = _parse_decimal(params["cursor"])
        if parsed is None:
            return 400, {"error": "cursor must be a non-negative decimal"}
        cursor = parsed

    with self.store.lock:
        # Resolve the anchor against the persisted main chain inside
        # the same lock that builds the rows, so the anchor decision,
        # the entries and the pagination share one chain snapshot;
        # candidate forks are never consulted.
        if anchor_present:
            anchor_block = self.store.block_at(at_height)
            if (
                anchor_block is None
                or anchor_block.status != STATUS_CONFIRMED
            ):
                return 404, {"error": "anchor_not_found"}
            if anchor_block.block_hash != at_hash:
                return 409, {"error": "anchor_conflict"}
        rows: list[dict] = []
        for block in self.store.chain:
            if block.status != STATUS_CONFIRMED:
                continue
            if at_height is not None and block.height > at_height:
                break
            if height is not None and block.height != height:
                continue
            if min_height is not None and block.height < min_height:
                continue
            if max_height is not None and block.height > max_height:
                continue
            for index, tx in enumerate(block.transactions):
                if tx_id is not None and tx.tx_id != tx_id:
                    continue
                if account is not None:
                    # A self-transfer matches every direction and is
                    # listed once, since each transaction is tested once.
                    if direction == "out":
                        if tx.sender != account:

                            continue
                    elif direction == "in":
                        if tx.recipient != account:
                            continue
                    elif account not in (tx.sender, tx.recipient):
                        continue
                rows.append(
                    {
                        "tx_id": tx.tx_id,
                        "height": block.height,
                        "block_hash": block.block_hash,
                        "index": index,
                        "from": tx.sender,
                        "to": tx.recipient,
                        "amount": tx.amount,
                    }
                )
    # Chain order is already (height, index) ascending; the tx_id
    # tiebreaker is implied because ids are unique within a block.
    total = len(rows)
    if cursor > total:
        return 400, {"error": "cursor is beyond the result set"}
    items = rows[cursor : cursor + limit]
    next_cursor = cursor + limit if cursor + limit < total else None
    body: dict = {"items": items, "total": total, "next_cursor": next_cursor}
    if include_summary:
        # The summary covers the WHOLE filtered set (all confirmed rows
        # collected above), never just the current page. Direction filters
        # transactions first; each surviving row is then re-classified by
        # the account independently, so a self-transfer counts once as
        # incoming and once as outgoing while occupying a single total.
        # All arithmetic stays on Python integers.
        incoming_count = 0
        outgoing_count = 0
        incoming_amount = 0
        outgoing_amount = 0
        for row in rows:
            if row["to"] == account:
                incoming_count += 1
                incoming_amount += row["amount"]
            if row["from"] == account:
                outgoing_count += 1
                outgoing_amount += row["amount"]
        body["summary"] = {
            "incoming_count": incoming_count,
            "outgoing_count": outgoing_count,
            "incoming_amount": incoming_amount,
            "outgoing_amount": outgoing_amount,
            "net_amount": incoming_amount - outgoing_amount,
        }
    return 200, body

# -- source trust registry ------------------------------------------------

@staticmethod
def _trust_record(source: str, rec: dict) -> dict:
    """Public shape of one trust-source record."""
    return {
        "source": source,
        "public_key": rec["public_key"],
        "expires_at": rec["expires_at"],
        "version": rec["version"],
        "status": rec["status"],
    }

def _validate_trust_input(self, payload: object, require_version: bool) -> tuple | None:
    """Validate a trust registration/rotation body.

    ``source`` must be a non-empty string, ``public_key`` 64 lowercase
    hex characters and ``expires_at`` a plain (non-boolean) integer.
    Rotation/revocation additionally require a positive integer
    ``expected_version``. Returns (source, public_key, expires_at[,
    expected_version]) or None after sending a 400.
    """
    if not isinstance(payload, dict):
        return None
    for field in ("source", "public_key", "expires_at"):
        if field not in payload:
            return None
    source = payload["source"]
    public_key = payload["public_key"]
    expires_at = payload["expires_at"]
    if not isinstance(source, str) or not source:
        return None
    if not crypto.is_hex64(public_key):
        return None
    if isinstance(expires_at, bool) or not isinstance(expires_at, int):
        return None
    if not require_version:
        return source, public_key, expires_at
    expected_version = payload.get("expected_version")
    if (
        isinstance(expected_version, bool)
        or not isinstance(expected_version, int)
        or expected_version < 1
    ):
        return None
    return source, public_key, expires_at, expected_version

def register_trust_source(self, payload: object) -> tuple[int, dict]:
    """POST /v1/trust/sources — register a trusted source.

    A new source is created at version 1 with status ``active`` and the
    change is persisted together with its audit event in one atomic write
    (201). Re-posting the exact same (public_key, expires_at) content is
    idempotent (200, the stored record unchanged); the same source with
    different content conflicts (409).
    """
    if not isinstance(payload, dict):
        return 400, {"error": "request body must be a JSON object"}
    for field in ("source", "public_key", "expires_at"):
        if field not in payload:
            return 400, {"error": f"missing field: {field}"}
    parsed = self._validate_trust_input(payload, require_version=False)
    if parsed is None:
        return 400, {
            "error": "source must be a non-empty string, public_key 64 "
            "lowercase hex characters and expires_at an integer"
        }
    source, public_key, expires_at = parsed

"""Data models for transactions and blocks."""
from __future__ import annotations

import json
from dataclasses import dataclass

from . import crypto

# Block lifecycle states for the confirm/rollback state machine.
STATUS_PENDING = "pending"
STATUS_CONFIRMED = "confirmed"
BLOCK_STATUSES = (STATUS_PENDING, STATUS_CONFIRMED)


@dataclass
class Transaction:
    sender: str
    recipient: str
    amount: int
    signature: str
    # None marks a legacy transfer signed over crypto.canonical_message; a
    # non-boolean non-negative integer marks a sequenced transfer signed over
    # crypto.sequenced_message and bound to the sender's per-account sequence.
    nonce: int | None = None

    @property
    def message(self) -> bytes:
        if self.nonce is None:
            return crypto.canonical_message(self.sender, self.recipient, self.amount)
        return crypto.sequenced_message(
            self.sender, self.recipient, self.amount, self.nonce
        )

    @property
    def tx_id(self) -> str:
        return crypto.compute_tx_id(self.message)

    @property
    def sequenced(self) -> bool:
        return self.nonce is not None

    def to_dict(self) -> dict:
        """JSON-safe representation used both for storage and API output."""
        result = {
            "from": self.sender,
            "to": self.recipient,
            "amount": self.amount,
            "signature": self.signature,
        }
        # The nonce is present only on sequenced transfers, so a legacy
        # transaction keeps its exact five-field wire shape.
        if self.nonce is not None:
            result["nonce"] = self.nonce
        result["tx_id"] = self.tx_id
        return result

    @classmethod
    def from_dict(cls, data: dict) -> "Transaction":
        # The raw JSON value is validated BEFORE any use: no int()/str()
        # coercion, so a string, float or boolean amount can never masquerade
        # as the integer it converts to. bool is an int subclass and must be
        # rejected explicitly.
        amount = data["amount"]
        if isinstance(amount, bool) or not isinstance(amount, int):
            raise ValueError("transaction amount must be an integer")
        # A present nonce must already be a non-boolean, non-negative integer
        # — never a coercible string, float, bool or negative. A missing key
        # denotes a legacy transfer and stays None.
        nonce = data.get("nonce")
        if nonce is not None and (
            isinstance(nonce, bool) or not isinstance(nonce, int) or nonce < 0
        ):
            raise ValueError("transaction nonce must be a non-negative integer")
        return cls(
            sender=data["from"],
            recipient=data["to"],
            amount=amount,
            signature=data["signature"],
            nonce=nonce,
        )


def block_header_bytes(height: int, prev_hash: str, merkle: str) -> bytes:
    """Deterministic serialization of the fields covered by the block hash.

    No timestamp is included: a block with the same parent and the same ordered
    transactions must always hash identically.
    """
    header = {"height": height, "merkle_root": merkle, "prev_hash": prev_hash}
    return json.dumps(header, sort_keys=True, separators=(",", ":")).encode("utf-8")


def compute_block_hash(height: int, prev_hash: str, merkle: str) -> str:
    return crypto.sha256_hex(block_header_bytes(height, prev_hash, merkle))


@dataclass
class Block:
    height: int
    prev_hash: str
    merkle_root: str
    transactions: list[Transaction]
    block_hash: str
    status: str = STATUS_CONFIRMED

    @classmethod
    def create(
        cls,
        height: int,
        prev_hash: str,
        transactions: list[Transaction],
        status: str = STATUS_CONFIRMED,
    ) -> "Block":
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        ordered = sorted(transactions, key=lambda tx: tx.tx_id)
        merkle = crypto.merkle_root([tx.tx_id for tx in ordered])
        block_hash = compute_block_hash(height, prev_hash, merkle)
        return cls(
            height=height,
            prev_hash=prev_hash,
            merkle_root=merkle,
            transactions=ordered,
            block_hash=block_hash,
            status=status,
        )

    def to_dict(self) -> dict:
        return {
            "height": self.height,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "block_hash": self.block_hash,
            "status": self.status,
            "transactions": [tx.to_dict() for tx in self.transactions],
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Block":
        # State files written before the status machine existed have no
        # "status" key; every block in such a file was final, so they load
        # as confirmed. This compatibility default never extends to numeric
        # coercion: the raw height must already be a non-boolean,
        # non-negative integer — a string, float or bool is rejected, never
        # converted.
        status = data.get("status", STATUS_CONFIRMED)
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        height = data["height"]
        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            raise ValueError("block height must be a non-negative integer")
        transactions = data["transactions"]
        if not isinstance(transactions, list):
            raise ValueError("block transactions must be a list")
        return cls(
            height=height,
            prev_hash=data["prev_hash"],
            merkle_root=data["merkle_root"],
            block_hash=data["block_hash"],
            transactions=[Transaction.from_dict(t) for t in transactions],
            status=status,
        )

    def to_summary(self) -> dict:
        """Response shape for GET /v1/blocks/{height}."""
        return {
            "height": self.height,
            "block_hash": self.block_hash,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "status": self.status,
            "transaction_ids": [tx.tx_id for tx in self.transactions],
        }

